insert into public.topics
  (id, position, title, category, description, subtopics, goal, link)
values
  (1, 1, 'Introduction to Machine Learning', 'Суурь', 'Machine Learning нь компьютерт өгөгдлөөс суралцах чадвар олгодог салбар юм.', array['What is an ML Engineer?', 'ML Engineer vs AI Engineer', 'Skills and Responsibilities'], 'ML-ийн үндсэн ойлголт, ML инженерийн ажлыг тайлбарлаж чаддаг болох.', 'https://developers.google.com/machine-learning/crash-course'),
  (2, 2, 'Mathematical Foundations', 'Суурь', 'ML алгоритмуудыг ойлгоход шаардлагатай математикийн үндэс.', array['Linear Algebra', 'Calculus', 'Statistics', 'Probability', 'Discrete Mathematics'], 'Вектор, матриц, уламжлал, магадлалын үндсэн ойлголтыг мэдэх.', 'https://www.khanacademy.org/math/linear-algebra'),
  (3, 3, 'Python for Machine Learning', 'Суурь', 'Python бол ML-д хамгийн их хэрэглэгддэг програмчлалын хэл.', array['Basic Syntax', 'Variables and Data Types', 'Conditionals', 'Loops', 'Data Structures', 'Functions', 'Exceptions', 'Object Oriented Programming'], 'Энгийн Python програм бичиж чаддаг болох.', 'https://docs.python.org/3/tutorial/'),
  (4, 4, 'Essential Libraries', 'Суурь', 'ML-д байнга хэрэглэгддэг Python сангууд.', array['NumPy', 'Pandas', 'Matplotlib', 'Seaborn'], 'NumPy, Pandas ашиглан өгөгдөл уншиж, график зурж сурах.', 'https://numpy.org/learn/'),
  (5, 5, 'Data Collection', 'Өгөгдөл', 'Загвар сургахад шаардлагатай өгөгдлийг цуглуулах, олох арга.', array['Databases (SQL, NoSQL)', 'Internet APIs', 'Mobile Apps, IoT', 'CSV, JSON', 'Parquet, Excel'], 'Өөрийн төсөлд тохирох өгөгдлийг олж, ачаалж чаддаг болох.', 'https://www.kaggle.com/datasets'),
  (6, 6, 'Data Cleaning and Preprocessing', 'Өгөгдөл', 'Өгөгдлийг загварт оруулахаас өмнө цэвэрлэж, бэлтгэх үе шат.', array['Data Cleaning', 'Preprocessing Techniques', 'Dimensionality Reduction'], 'Эмх замбараагүй өгөгдлийг цэвэрлэж, загварт бэлтгэх.', 'https://www.kaggle.com/learn/data-cleaning'),
  (7, 7, 'Feature Engineering', 'Өгөгдөл', 'Өгөгдлөөс загварт илүү хэрэгтэй шинж чанаруудыг (feature) бэлтгэх.', array['Feature Selection', 'Feature Scaling & Normalization'], 'Загварын чанарыг сайжруулах feature-үүдийг боловсруулж чаддаг болох.', 'https://www.kaggle.com/learn/feature-engineering'),
  (8, 8, 'Types of Machine Learning', 'ML алгоритм', 'Machine Learning-ийн үндсэн төрлүүд, тэдгээрийн ялгаа.', array['Supervised Learning', 'Unsupervised Learning', 'Semi-supervised Learning', 'Self-supervised Learning', 'Reinforcement Learning'], 'ML-ийн төрөл бүрийг хэзээ хэрэглэхийг ялгаж мэдэх.', 'https://scikit-learn.org/stable/user_guide.html'),
  (9, 9, 'Supervised Learning', 'ML алгоритм', 'Supervised Learning нь шошготой өгөгдөл ашиглан загвар сургах Machine Learning-ийн төрөл юм.', array['Classification', 'Regression', 'Training data ба Testing data', 'Model prediction'], 'Supervised Learning-ийн үндсэн ойлголтыг мэдэж, энгийн өгөгдөл дээр загвар сургах.', 'https://scikit-learn.org/stable/supervised_learning.html'),
  (10, 10, 'Regression', 'ML алгоритм', 'Тасралтгүй тоон утгыг (үнэ, температур гэх мэт) таамаглах арга.', array['Linear Regression', 'Polynomial Regression'], 'Linear Regression загварыг сургаж, үр дүнг тайлбарлах.', 'https://developers.google.com/machine-learning/crash-course/linear-regression'),
  (11, 11, 'Classification', 'ML алгоритм', 'Өгөгдлийг ангилал (класс)-д хуваарилах арга.', array['Logistic Regression', 'Support Vector Machines', 'K-Nearest Neighbors (KNN)', 'Decision Trees, Random Forest', 'Gradient Boosting Machines'], 'Энгийн ангиллын загвар сургаж, таамаглал гаргах.', 'https://developers.google.com/machine-learning/crash-course/classification'),
  (12, 12, 'Unsupervised Learning', 'ML алгоритм', 'Шошгогүй өгөгдлөөс нууц хэв маяг, бүтцийг олох арга.', array['Clustering', 'Dimensionality Reduction', 'Principal Component Analysis', 'Autoencoders'], 'K-Means, PCA зэрэг аргыг энгийн өгөгдөл дээр ашиглаж чаддаг болох.', 'https://scikit-learn.org/stable/unsupervised_learning.html'),
  (13, 13, 'Reinforcement Learning', 'ML алгоритм', 'Agent орчинтой харилцаж, шагналаар дамжуулан суралцах арга.', array['Q-Learning', 'Deep-Q Networks', 'Policy Gradient', 'Actor-Critic Methods'], 'Reinforcement Learning-ийн үндсэн ойлголтыг тайлбарлах.', 'https://huggingface.co/learn/deep-rl-course'),
  (14, 14, 'Model Evaluation', 'Үнэлгээ', 'Загвар хэр сайн ажиллаж байгааг хэмжих, шалгах арга.', array['Accuracy, Precision, Recall', 'F1-Score', 'ROC-AUC, Log Loss', 'Confusion Matrix', 'K-Fold Cross Validation', 'LOOCV', 'Lasso, Ridge, ElasticNet'], 'Загварыг зөв хэмжүүрээр үнэлж, overfitting-ийг таньж чаддаг болох.', 'https://scikit-learn.org/stable/modules/model_evaluation.html'),
  (15, 15, 'Deep Learning and Neural Networks', 'Deep Learning', 'Олон давхарга бүхий мэдрэлийн сүлжээгээр суралцах ML-ийн салбар.', array['Perceptron, Multi-layer Perceptron', 'Activation Functions', 'Loss Functions', 'Forward Propagation', 'Back Propagation', 'TensorFlow, Keras', 'PyTorch'], 'Энгийн Neural Network-ийг өөрөө бүтээж сургах.', 'https://www.kaggle.com/learn/intro-to-deep-learning'),
  (16, 16, 'Deep Learning Architectures', 'Deep Learning', 'Зураг, дараалсан өгөгдөл, текст зэрэгт зориулсан сүлжээний бүтцүүд.', array['Convolutional Neural Network (CNN)', 'Recurrent Neural Network (RNN, LSTM, GRU)', 'Transformers', 'Self-Attention, Multi-head Attention', 'Generative Adversarial Networks'], 'CNN, RNN, Transformer-ийн ялгаа, хэрэглээг мэдэх.', 'https://www.3blue1brown.com/topics/neural-networks'),
  (17, 17, 'Natural Language Processing', 'Deep Learning', 'Компьютерт хүний хэлийг (текст) боловсруулж ойлгуулах салбар.', array['Tokenization', 'Stemming', 'Lemmatization', 'Embeddings', 'Attention Models'], 'Текстийг боловсруулж, энгийн NLP даалгавар хийх.', 'https://huggingface.co/learn/nlp-course'),
  (18, 18, 'Final Project', 'Төсөл', 'Сурсан бүх зүйлээ нэгтгэн бодит төсөл хийх.', array['Асуудал сонгох', 'Өгөгдөл бэлтгэх', 'Загвар сургах, үнэлэх', 'Үр дүнг танилцуулах'], 'Эхнээс нь дуустал нэг ML төслийг бие даан хийж дуусгах.', 'https://www.kaggle.com/competitions')
